class Solution {
public:
    long long minimumReplacement(std::vector<int>& nums) {
        long long ans = 0;
        int limit = nums.back();
        for (int i = (int)nums.size() - 2; i >= 0; --i) {
            if (nums[i] > limit) {
                long long parts = ((long long)nums[i] + limit - 1) / limit;
                ans += parts - 1;
                limit = nums[i] / parts;
            } else {
                limit = nums[i];
            }
        }
        return ans;
    }
};

class Solution {
    public long minimumReplacement(int[] nums) {
        long ans = 0;
        int limit = nums[nums.length - 1];
        for (int i = nums.length - 2; i >= 0; --i) {
            if (nums[i] > limit) {
                long parts = ((long) nums[i] + limit - 1) / limit;
                ans += parts - 1;
                limit = (int) (nums[i] / parts);
            } else {
                limit = nums[i];
            }
        }
        return ans;
    }
}

var minimumReplacement = function(nums) {
    let ans = 0n;
    let limit = BigInt(nums[nums.length - 1]);
    for (let i = nums.length - 2; i >= 0; --i) {
        const val = BigInt(nums[i]);
        if (val > limit) {
            const parts = (val + limit - 1n) / limit;
            ans += parts - 1n;
            limit = val / parts;
        } else {
            limit = val;
        }
    }
    return Number(ans);
};
